      "privacy_a3_r1_b": "Étapes précontractuelles",
      "privacy_a3_r2_p": "Exécution de services commandés",
      "privacy_a3_r2_d": "Identification, coordonnées, données de projet",
      "privacy_a3_r2_b": "Exécution du contrat",
      "privacy_a3_r3_p": "Facturation et obligations comptables",
      "privacy_a3_r3_d": "Données de facturation, historique des commandes",
      "privacy_a3_r3_b": "Obligation légale",
